import {
  type AccountRef,
  accountRefSchema,
  type AssetRef,
  assetRefSchema,
  type ChainRef,
  chainRefSchema,
  type LaunchLog,
} from "@binference/plugin-sdk";

// Two launches through BrewFactory on BSC against WBNB: the logs of the events the venue declares
// for the launch feed, recorded from BNB Chain's public node on 2026-10-20.

const account = (address: string): AccountRef => accountRefSchema.parse(`eip155:56:${address}`);
const token = (address: string): AssetRef => assetRefSchema.parse(`eip155:56/erc20:${address}`);

/** BNB Smart Chain, which the recorded launches ran on. */
export const bscChain: ChainRef = chainRefSchema.parse("eip155:56");

/** BNB, the coin the recorded launches trade against through WBNB. */
export const bnb: AssetRef = assetRefSchema.parse("eip155:56/slip44:714");

/** WBNB, the wrapped coin the recorded pools hold. */
export const wbnb: AssetRef = token("0xbb4CdB9CBd36B01bD1cBaEBF2De08d9173bc095c");

/** BrewFactory as the registry lists it, by name. */
export const registryContracts: Readonly<Record<string, AccountRef>> = {
  factory: account("0xeEa6C3bfb29Fd9a35380438956bae7B109c63d85"),
};

/** A contract the venue does not know: BrewMultiPairFactory, whose launches binference leaves out. */
export const multiPairFactory: AccountRef = account("0x21653fa9c9562d55a162c17D2eF33Fc0FaB7Ea71");

const factory = registryContracts["factory"] ?? multiPairFactory;

