/** A recorded launch: its token, its creator, its `TokenLaunched` log and all its logs. */
export interface RecordedLaunch {
  readonly token: AssetRef;
  readonly creator: AccountRef;
  readonly created: LaunchLog;
  readonly logs: readonly LaunchLog[];
}

/** Heyi.ai (HEYI) with a 1 BNB first buy for its creator, whose log is `bought`. */
export const boughtLaunch: RecordedLaunch & { readonly bought: LaunchLog } = {
  token: token("0x22AF5f3e7Cffc576d94FfdacB48eb0082D476666"),
  creator: account("0xA66B919a324d3E61Ba3478383C5a77e86B30AD2d"),
  created: heyiCreated,
  bought: heyiBought,
  logs: [heyiCreated, heyiBought],
};

